$update_db[]="CREATE TABLE `".$table_prefix."_XXXroom` (
	`id_room` INT NOT NULL AUTO_INCREMENT,
  `id_ward` INT NULL DEFAULT NULL,
	`roomname` VARCHAR(50) NOT NULL DEFAULT '',
	`image` BLOB NULL DEFAULT NULL,
	`web_url` VARCHAR(255) NULL DEFAULT NULL,
	`custom_field` TEXT NULL DEFAULT NULL COMMENT 'Riferimenti generici utilizzabili sui moduli. Normalmente in formato json: {\"nome_modulo\":{\"nome_variabile\":{\"valore_variabile\": {}}}}',
	`note_other` VARCHAR(50) NULL DEFAULT NULL,
	`status` VARCHAR(10) NOT NULL DEFAULT '',
	`adminid` VARCHAR(20) NOT NULL DEFAULT '',
	`last_modified` TIMESTAMP NULL DEFAULT (CURRENT_TIMESTAMP) ON UPDATE CURRENT_TIMESTAMP,
	INDEX `id_ward` (`id_ward`) USING BTREE,
	INDEX `status` (`status`) USING BTREE,
	PRIMARY KEY (`id_room`) USING BTREE);";

$update_db[]="CREATE TABLE `".$table_prefix."_XXXbed` (
	`id_bed` INT NOT NULL AUTO_INCREMENT,
  `id_room` INT NULL DEFAULT NULL,
	`bedname` VARCHAR(50) NOT NULL DEFAULT '',
	`image` BLOB NULL DEFAULT NULL,
	`web_url` VARCHAR(255) NULL DEFAULT NULL,
	`custom_field` TEXT NULL DEFAULT NULL COMMENT 'Riferimenti generici utilizzabili sui moduli. Normalmente in formato json: {\"nome_modulo\":{\"nome_variabile\":{\"valore_variabile\": {}}}}',
	`note_other` VARCHAR(50) NULL DEFAULT NULL,
	`status` VARCHAR(10) NOT NULL DEFAULT '',
	`adminid` VARCHAR(20) NOT NULL DEFAULT '',
	`last_modified` TIMESTAMP NULL DEFAULT (CURRENT_TIMESTAMP) ON UPDATE CURRENT_TIMESTAMP,
	INDEX `id_room` (`id_room`) USING BTREE,
	INDEX `status` (`status`) USING BTREE,
	PRIMARY KEY (`id_bed`) USING BTREE);";

$update_db[]="CREATE TABLE `".$table_prefix."_XXXward` (
	`id_ward` INT NOT NULL AUTO_INCREMENT,
	`wardname` VARCHAR(50) NOT NULL DEFAULT '',
	`image` BLOB NULL DEFAULT NULL,
	`web_url` VARCHAR(255) NULL DEFAULT NULL,
	`custom_field` TEXT NULL DEFAULT NULL COMMENT 'Riferimenti generici utilizzabili sui moduli. Normalmente in formato json: {\"nome_modulo\":{\"nome_variabile\":{\"valore_variabile\": {}}}}',
	`note_other` VARCHAR(50) NULL DEFAULT NULL,
	`status` VARCHAR(10) NOT NULL DEFAULT '',
	`adminid` VARCHAR(20) NOT NULL DEFAULT '',
	`last_modified` TIMESTAMP NULL DEFAULT (CURRENT_TIMESTAMP) ON UPDATE CURRENT_TIMESTAMP,
	INDEX `status` (`status`) USING BTREE,
	PRIMARY KEY (`id_ward`) USING BTREE
);";

